# -*- coding: utf-8 -*-
"""
Dodaje polskie znaki do napisów w interfejsie, raportach i testach.
Uruchom z folderu projektu:   python add_polish.py [plik1 plik2 ...]
Bez argumentów przetwarza wszystkie pliki; z argumentami (ścieżki jak
w LISTA_PLIKOW) tylko wskazane -- wygodne przy osobnych commitach.
Można uruchamiać wielokrotnie (pliki już poprawione są pomijane).
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent

