LICZBA = {'webapp/reports.py': {'"Kendall tau", "Spearman rho"]': 2}}


def przetworz(sciezka):
    p = ROOT / sciezka
    if not p.exists():
        print("BRAK PLIKU:", sciezka)
        return
    if sciezka in PELNE_PLIKI:
        nowa = PELNE_PLIKI[sciezka]
        stara = p.read_text(encoding="utf-8")
        if stara == nowa:
            print("juz ok:", sciezka)
        else:
            p.write_text(nowa, encoding="utf-8", newline="\n")
            print("zapisano:", sciezka)
        return
    s = p.read_text(encoding="utf-8")
    zmieniono = 0
    for stare, nowe in ZAMIANY[sciezka]:
        if nowe in s:
            continue  # juz zamienione
        elif stare in s:
            s = s.replace(stare, nowe)
            zmieniono += 1
        else:
            print("  UWAGA: nie znaleziono fragmentu w %s: %r" % (sciezka, stare[:60]))
    if zmieniono:
        p.write_text(s, encoding="utf-8", newline="\n")
        print("zapisano:", sciezka, "(%d zmian)" % zmieniono)
    else:
        print("juz ok:", sciezka)


if __name__ == "__main__":
    wszystkie = list(PELNE_PLIKI) + list(ZAMIANY)
    cele = sys.argv[1:] or wszystkie
    for c in cele:
        przetworz(c.replace("\\", "/"))
